"""Collect actual Q2 draft activations with an isolated MTP Host object; no timing claims."""
import copy
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys

import numpy as np
import practical as p

HERE = p.H / 'activation-calibration-r2'
CWD = p.R / 'build-orca-current-frontend-20261104/l0/build'
PROMPTS = [
    'Explain how a browser resolves a domain name and establishes an HTTPS connection. Use four short paragraphs.',
    'Describe the difference between a process and a thread, with a concrete example of each.',
    'Write a Python function that performs binary search on a sorted list and explain its boundary conditions.',
    'Write a Python iterator that reads a UTF-8 text file in fixed-size chunks and closes it on errors.',
    'Write SQL that finds customers with no orders, using LEFT JOIN and NOT EXISTS, and compare the two queries.',
    'Explain database transaction isolation levels with two concurrent bank transfers.',
    '请解释互斥锁和条件变量如何配合使用，并举一个生产者消费者的例子。',
    '请给出排查网页加载缓慢的步骤，涵盖网络、服务端和浏览器三个方面。',
    '请写一个 Python 函数，统计文本中每个单词出现的次数，说明如何处理大小写和标点。',
    '请解释什么是单元测试，并为一个计算购物车总价的函数列出五个测试用例。',
    'Translate this paragraph into Chinese, then explain two translation choices: A reliable service must recover from partial failures without duplicating payments.',
    'Write a concise README for a command-line tool that converts CSV files to JSON, including usage and error examples.',
]

TRACE_HELPER = r'''
// Calibration-only readback after a completed full draft; never used for performance samples.
bool calibration_snapshot(dpct::queue_ptr cs, int n, int ff, int k, int ne,
                          const float* mixed, const void* scratch, const int32_t* ids,
                          const int32_t* dst, std::string& err) {
    const char* path = std::getenv("STRATA_MTP_CALIBRATION_FILE");
    if (!path || !*path) return true;
    if (g_mtp_expert_type != 0) { err = "calibration requires Q2 experts"; return false; }
    static std::unique_ptr<FILE, int(*)(FILE*)> file(std::fopen(path, "wbx"), std::fclose);
    if (!file) { err = "cannot exclusively create calibration file"; return false; }
    static bool header = false;
    if (!header) {
        const int32_t shape[4] = {n, ff, k, ne};
        if (std::fwrite("MTPIMX1\0", 1, 8, file.get()) != 8 ||
            std::fwrite(shape, sizeof(int32_t), 4, file.get()) != 4) {
            err = "writing calibration header failed"; return false;
        }
        header = true;
        std::fprintf(stderr, "strata mtp: collecting Q2 activation calibration\n");
    }
    std::vector<int32_t> routing((size_t) k * 2);
    std::vector<float> activation((size_t) n + (size_t) k * ff);
    cs->memcpy(routing.data(), ids, (size_t) k * sizeof(int32_t));
    cs->memcpy(routing.data() + k, dst, (size_t) k * sizeof(int32_t));
    cs->memcpy(activation.data(), mixed, (size_t) n * sizeof(float));
    cs->memcpy(activation.data() + n, scratch, (size_t) k * ff * sizeof(float));
    cs->wait_and_throw();
    std::vector<int> seen((size_t) k, 0);
    for (int i = 0; i < k; ++i) {
        if (routing[i] < 0 || routing[i] >= ne || routing[k + i] < 0 || routing[k + i] >= k ||
            seen[(size_t) routing[k + i]]++) {
            err = "invalid calibration route permutation"; return false;
        }
    }
    for (float v : activation) if (!std::isfinite(v)) {
        err = "nonfinite calibration activation"; return false;
    }
    if (std::fwrite(routing.data(), sizeof(int32_t), routing.size(), file.get()) != routing.size() ||
        std::fwrite(activation.data(), sizeof(float), activation.size(), file.get()) != activation.size()) {
        err = "writing calibration record failed"; return false;
    }
    if (std::fflush(file.get()) != 0) { err = "flushing calibration record failed"; return false; }
    return true;
}
'''


def prepare():
    HERE.mkdir()
    source = (p.H / 'mtp.cpp').read_text(encoding='utf8')
    source = source.replace('#include <algorithm>', '#include <algorithm>\n#include <cmath>\n#include <memory>', 1)
    assert source.count('struct Bump {') == 1
    source = source.replace('struct Bump {', TRACE_HELPER + '\nstruct Bump {', 1)
    call = 'if (!calibration_snapshot(cs_, (int) g_->n_embd, (int) g_->n_ff, (int) ss_->k, (int) g_->n_expert, mixed_, hit_scratch_, ids_, hit_dst_, err)) return false;'
    for anchor in ('    drafts[0] = ((volatile int32_t*) h_out_)[0];',
                   '        drafts[j] = ((volatile int32_t*) h_out_)[j];'):
        assert source.count(anchor) == 1
        source = source.replace(anchor, '    ' + call + '\n' + anchor, 1)
    (HERE / 'mtp.cpp').write_text(source, encoding='utf8')
    compile_text = (p.H / 'compile.cmd').read_text().replace(str(p.H / 'mtp.'), str(HERE / 'mtp.'))
    compile_text = compile_text.replace(str(p.H / 'compile.pdb'), str(HERE / 'compile.pdb'))
    compile_text = compile_text.replace((p.H / 'compile.pdb').as_posix(), (HERE / 'compile.pdb').as_posix())
    (HERE / 'compile.cmd').write_text(compile_text)
    link = (p.H / 'link-current.cmd').read_text().replace(str(p.H / 'mtp.obj'), str(HERE / 'mtp.obj'))
    for suffix in ('exe', 'lib', 'pdb'):
        link = link.replace(str(p.H / ('strata-u4.' + suffix)), str(HERE / ('strata.' + suffix)))
    (HERE / 'link.cmd').write_text(link)
    # Use the existing tokenizer and template; calibration prompts are separate from evaluation inputs.
    cfg = json.loads((p.R / 'strata-iq2_xs.json').read_text(encoding='utf8'))
    sys.path.insert(0, str(p.R))
    from strata_tokenizer import Tokenizer
    from serve.frontend import ChatTemplate, openai_to_messages
    directory = Path(cfg['tokenizer'])
    vocab = json.loads((directory / 'vocab.json').read_text(encoding='utf8'))
    tokens = [None] * len(vocab)
    for token, number in vocab.items():
        tokens[number] = token
    tokenizer = Tokenizer(tokens, (directory / 'merges.txt').read_text(encoding='utf8').splitlines(),
                          json.loads((directory / 'token_type.json').read_text(encoding='utf8')))
    template = ChatTemplate(directory / 'chat_template.jinja')
    ids = []
    for prompt in PROMPTS:
        messages, tools, kwargs = openai_to_messages(dict(messages=[dict(role='user', content=prompt)], reasoning_effort='none'))
        ids.append(tokenizer.encode(template.render(messages, tools, **kwargs), parse_special=True))
    p.b.save(HERE / 'prepared.json', dict(config=cfg, prompts=PROMPTS, inputs=ids,
                                        source_sha256=p.b.sha(HERE / 'mtp.cpp'), runner=Path(__file__).read_text()))
    print('PREPARED calibration source and', len(ids), 'independent prompts', flush=True)


def collect():
    data = json.loads((HERE / 'prepared.json').read_text(encoding='utf8'))
    result = dict(complete=False, rows=[], reference_rows=[])
    p.b.save(HERE / 'results.json', result)
    assert CWD.is_dir()
    for name in ('strata_orca_engine.lib', 'strata_orca_host.lib', 'strata_orca_cpu.lib',
                 'runtime/orca_l0.lib', 'ggml/src/ggml-cpu.lib', 'ggml/src/ggml-base.lib'):
        assert (CWD / name).is_file(), name
    with p.b.gpu_lock():
        for name in ('compile', 'link'):
            with (HERE / (name + '.log')).open('x') as log:
                subprocess.run(['cmd', '/c', str(HERE / (name + '.cmd'))], cwd=CWD,
                               stdout=log, stderr=log, check=True, timeout=300)
            print('PASS calibration', name, flush=True)
        cfg = copy.deepcopy(data['config'])
        cfg['exe'] = str(HERE / 'strata.exe')
        cfg['env'].update(STRATA_MTP_CALIBRATION_FILE=str(HERE / 'activation.bin'),
                          STRATA_MTP_CUM_MIN_P='0', STRATA_MTP_CHAIN_SUBMIT='0', STRATA_MTP_EXPERTS='q2_0')
        references = json.loads((p.H / 'gated-current-r1/results.json').read_text(encoding='utf8'))['runs'][0]['rows']
        warm_ids = json.loads((p.H / 'gated-current-r1-inputs.json').read_text(encoding='utf8'))
        with_engine = p.b.Engine.__new__(p.b.Engine)
        try:
            with_engine.__init__(Path(cfg['exe']), cfg['args'], p.environment(cfg), HERE / 'collect')
            result['info'] = with_engine.info
            result['initializer'] = with_engine.gen(warm_ids['Chinese'], 16, keys='temperature=0')
            # These two audit requests are excluded from calibration moments by their trace record ranges.
            for row in references[:2]:
                before = (HERE / 'activation.bin').stat().st_size
                got = with_engine.gen(warm_ids[row['case']], 128, keys='temperature=0')
                after = (HERE / 'activation.bin').stat().st_size
                assert all(got[k] == row[k] for k in p.KEYS)
                result['reference_rows'].append(dict(case=row['case'], row=got, excluded_bytes=[before, after]))
            for i, ids in enumerate(data['inputs']):
                row = with_engine.gen(ids, 96, keys='temperature=0')
                result['rows'].append(row)
                p.b.save(HERE / 'results.json', result)
                print('CALIBRATION', i, 'tokens', row['generated'], flush=True)
        finally:
            if hasattr(with_engine, 'p'):
                with_engine.close()
                result['exit_code'] = with_engine.p.returncode
            p.b.save(HERE / 'results.json', result)
        assert result['exit_code'] == 0
        result.update(complete=True, trace_sha256=p.b.sha(HERE / 'activation.bin'),
                      exe_sha256=p.b.sha(HERE / 'strata.exe'), source_sha256=p.b.sha(HERE / 'mtp.cpp'))
        p.b.save(HERE / 'results.json', result)


if __name__ == '__main__':
    {'prepare': prepare, 'collect': collect}[sys.argv[1]]()

